export interface CalendlyWebhookPayload {
  uri: string
  email: string
  name: string
  first_name: string
  last_name: string
  status: string
  timezone: string
  event: string
  cancel_url: string
  reschedule_url: string
  questions_and_answers: Array<{
    question: string
    answer: string
    position: number
  }>
  tracking?: Record<string, string>
}

export interface CalendlyWebhookEvent {
  event: 'invitee.created'
  created_at: string
  created_by: string
  payload: CalendlyWebhookPayload
}

export type ConnectorInput = CalendlyWebhookEvent

export interface ConnectorConfig {
  fetch: typeof fetch
  slackBotToken: string
  slackChannel: string
  calendlySigningKey: string
  webhookSignature?: string
  webhookRawBody?: string
}

export interface ConnectorResult {
  slackMessageTs: string
  slackChannel: string
}

function verifySignature(signingKey: string, rawBody: string, signatureHeader: string): boolean {
  const crypto = globalThis.crypto
  if (!crypto?.subtle) {
    throw new Error('Web Crypto API not available for signature verification')
  }
  const encoder = new TextEncoder()
  const keyData = encoder.encode(signingKey)
  const messageData = encoder.encode(rawBody)
  return crypto.subtle.importKey('hmac', { name: 'HMAC', hash: 'SHA-256' }, keyData, false, ['verify'])
    .then((key) => crypto.subtle.verify('HMAC', key, encoder.encode(signatureHeader), messageData))
    .catch(() => false)
}

async function verifySignatureSync(signingKey: string, rawBody: string, signatureHeader: string): Promise<boolean> {
  const encoder = new TextEncoder()
  const key = await crypto.subtle.importKey(
    'raw',
    signingKey,
    { name: 'HMAC', hash: 'SHA-256' },
    false,
    ['verify']
  )
  const signatureBytes = encoder.encode(signatureHeader)
  const messageBytes = encoder.encode(rawBody)
  return crypto.subtle.verify('HMAC', key, signatureBytes, messageBytes)
}

function formatAnswers(questionsAndAnswers: CalendlyWebhookPayload['questions_and_answers']): string {
  if (!questionsAndAnswers || questionsAndAnswers.length === 0) {
    return 'No custom answers provided'
  }
  const sorted = [...questionsAndAnswers].sort((a, b) => a.position - b.position)
  return sorted.map((qa) => `${qa.question} -> ${qa.answer}`).join(', ')
}

function buildSlackText(payload: CalendlyWebhookPayload): string {
  const name = payload.name || `${payload.first_name} ${payload.last_name}`.trim()
  const email = payload.email
  const answers = formatAnswers(payload.questions_and_answers)
  return `New meeting booked!\nName: ${name}\nEmail: ${email}\nAnswers: ${answers}`
}

export async function handle(payload: ConnectorInput, config: ConnectorConfig): Promise<ConnectorResult> {
  if (!payload || typeof payload !== 'object') {
    throw new Error('Invalid payload: expected an object')
  }
  if (payload.event !== 'invitee.created') {
    throw new Error(`Unsupported event type: ${payload.event}`)
  }
  if (!payload.payload) {
    throw new Error('Missing payload in webhook event')
  }
  const { payload: invitee } = payload
  if (!invitee.name && !invitee.first_name) {
    throw new Error('Missing required field: invitee.name or invitee.first_name')
  }
  if (!invitee.email) {
    throw new Error('Missing required field: invitee.email')
  }
  if (!Array.isArray(invitee.questions_and_answers)) {
    throw new Error('Missing required field: invitee.questions_and_answers')
  }

  if (config.calendlySigningKey && config.webhookSignature && config.webhookRawBody) {
    const isValid = await verifySignatureSync(config.calendlySigningKey, config.webhookRawBody, config.webhookSignature)
    if (!isValid) {
      throw new Error('Invalid webhook signature')
    }
  }

  const text = buildSlackText(invitee)
  const body = JSON.stringify({ channel: config.slackChannel, text })

  const response = await config.fetch('https://slack.com/api/chat.postMessage', {
    method: 'POST',
    headers: {
      'Authorization': `Bearer ${config.slackBotToken}`,
      'Content-Type': 'application/json',
    },
    body,
  })

  if (!response.ok) {
    const errorText = await response.text().catch(() => '')
    throw new Error(`Slack API error (${response.status} ${response.statusText}): ${errorText}`)
  }

  const data = await response.json() as { ok: boolean; channel: string; ts: string; message?: { ts: string } }
  if (!data.ok) {
    throw new Error('Slack API returned ok: false')
  }

  return {
    slackMessageTs: data.message?.ts || data.ts,
    slackChannel: data.channel,
  }
}

import { describe, it, expect, vi, beforeEach } from 'vitest'
import { handle, ConnectorInput, ConnectorConfig } from './connector'
import { SOURCE_EXAMPLE, TARGET_ENDPOINTS, contractFetch, fakeFetch, jsonResponse, RecordedCall } from './fixtures'

describe('contract', () => {
  it('handles the documented example payload', async () => {
    const { fetch, calls } = contractFetch()
    const config: ConnectorConfig = {
      fetch,
      slackBotToken: 'xoxb-test-token',
      slackChannel: 'C1234567890',
      calendlySigningKey: 'test-signing-key',
      webhookSignature: 'valid-signature',
      webhookRawBody: JSON.stringify(SOURCE_EXAMPLE),
    }
    const result = await handle(SOURCE_EXAMPLE as unknown as ConnectorInput, config)
    expect(calls.length).toBeGreaterThan(0)
    expect(result.slackChannel).toBe('C1234567890')
    expect(result.slackMessageTs).toBe('1705317000.123456')
  })
})

describe('handle', () => {
  let baseConfig: ConnectorConfig
  let mockFetch: typeof fetch
  let calls: RecordedCall[]

  beforeEach(() => {
    const { fetch, calls: recordedCalls } = fakeFetch((req) => {
      if (req.url === 'https://slack.com/api/chat.postMessage' && req.method === 'POST') {
        return jsonResponse(TARGET_ENDPOINTS[0].response, 200)
      }
      return jsonResponse({ error: 'not found' }, 404)
    })
    mockFetch = fetch
    calls = recordedCalls
    baseConfig = {
      fetch: mockFetch,
      slackBotToken: 'xoxb-test-token',
      slackChannel: 'C1234567890',
      calendlySigningKey: 'test-signing-key',
      webhookSignature: 'valid-signature',
      webhookRawBody: JSON.stringify(SOURCE_EXAMPLE),
    }
  })

  it('posts formatted message to Slack on happy path', async () => {
    const result = await handle(SOURCE_EXAMPLE as unknown as ConnectorInput, baseConfig)
    expect(calls.length).toBe(1)
    const call = calls[0]
    expect(call.method).toBe('POST')
    expect(call.url).toBe('https://slack.com/api/chat.postMessage')
    expect(call.headers.get('authorization')).toBe('Bearer xoxb-test-token')
    expect(call.json).toEqual({
      channel: 'C1234567890',
      text: 'New meeting booked!\nName: Jane Doe\nEmail: jane@example.com\nAnswers: What is your company? -> Acme Corp, What is your role? -> Engineer',
    })
    expect(result.slackMessageTs).toBe('1705317000.123456')
    expect(result.slackChannel).toBe('C1234567890')
  })

  it('uses Bearer token authentication', async () => {
    await handle(SOURCE_EXAMPLE as unknown as ConnectorInput, baseConfig)
    const authHeader = calls[0].headers.get('authorization')
    expect(authHeader).toBe('Bearer xoxb-test-token')
  })

  it('maps invitee name, email, and answers to Slack text', async () => {
    await handle(SOURCE_EXAMPLE as unknown as ConnectorInput, baseConfig)
    const sentText = (calls[0].json as { text: string }).text
    expect(sentText).toContain('Name: Jane Doe')
    expect(sentText).toContain('Email: jane@example.com')
    expect(sentText).toContain('What is your company? -> Acme Corp')
    expect(sentText).toContain('What is your role? -> Engineer')
  })

  it('throws when invitee name is missing', async () => {
    const payload = {
      ...SOURCE_EXAMPLE,
      payload: { ...SOURCE_EXAMPLE.payload, name: undefined, first_name: undefined },
    } as unknown as ConnectorInput
    await expect(handle(payload, baseConfig)).rejects.toThrow('Missing required field: invitee.name or invitee.first_name')
  })

  it('throws when invitee email is missing', async () => {
    const payload = {
      ...SOURCE_EXAMPLE,
      payload: { ...SOURCE_EXAMPLE.payload, email: undefined },
    } as unknown as ConnectorInput
    await expect(handle(payload, baseConfig)).rejects.toThrow('Missing required field: invitee.email')
  })

  it('throws when questions_and_answers is missing', async () => {
    const payload = {
      ...SOURCE_EXAMPLE,
      payload: { ...SOURCE_EXAMPLE.payload, questions_and_answers: undefined },
    } as unknown as ConnectorInput
    await expect(handle(payload, baseConfig)).rejects.toThrow('Missing required field: invitee.questions_and_answers')
  })

  it('throws on non-2xx Slack response with status and endpoint', async () => {
    const { fetch, calls: errorCalls } = fakeFetch(() => jsonResponse({ error: 'invalid_auth' }, 401))
    const config = { ...baseConfig, fetch }
    await expect(handle(SOURCE_EXAMPLE as unknown as ConnectorInput, config)).rejects.toThrow(
      'Slack API error (401 Unauthorized): {"error":"invalid_auth"}'
    )
    expect(errorCalls[0].url).toBe('https://slack.com/api/chat.postMessage')
  })

  it('throws when webhook signature verification fails', async () => {
    const config = { ...baseConfig, webhookSignature: 'invalid-signature' }
    await expect(handle(SOURCE_EXAMPLE as unknown as ConnectorInput, config)).rejects.toThrow('Invalid webhook signature')
  })

  it('skips signature verification when signing key not provided', async () => {
    const config = { ...baseConfig, calendlySigningKey: '', webhookSignature: undefined, webhookRawBody: undefined }
    const result = await handle(SOURCE_EXAMPLE as unknown as ConnectorInput, config)
    expect(result.slackMessageTs).toBe('1705317000.123456')
  })

  it('formats answers correctly when empty', async () => {
    const payload = {
      ...SOURCE_EXAMPLE,
      payload: { ...SOURCE_EXAMPLE.payload, questions_and_answers: [] },
    } as unknown as ConnectorInput
    await handle(payload, baseConfig)
    const sentText = (calls[0].json as { text: string }).text
    expect(sentText).toContain('Answers: No custom answers provided')
  })

  it('constructs name from first_name and last_name when name missing', async () => {
    const payload = {
      ...SOURCE_EXAMPLE,
      payload: { ...SOURCE_EXAMPLE.payload, name: undefined, first_name: 'John', last_name: 'Smith' },
    } as unknown as ConnectorInput
    await handle(payload, baseConfig)
    const sentText = (calls[0].json as { text: string }).text
    expect(sentText).toContain('Name: John Smith')
  })
})

