function hexToBytes(hex: string): Uint8Array {
  const cleanHex = hex.replace(/^sha256=/, '')
  if (cleanHex.length % 2 !== 0) throw new Error('Invalid hex length')
  const bytes = new Uint8Array(cleanHex.length / 2)
  for (let i = 0; i < cleanHex.length; i += 2) {
    const byte = parseInt(cleanHex.substr(i, 2), 16)
    if (isNaN(byte)) throw new Error('Invalid hex character')
    bytes[i / 2] = byte
  }
  return bytes
}

async function verifySignature(signingKey: string, rawBody: string, signatureHeader: string): Promise<boolean> {
  const crypto = globalThis.crypto
  if (!crypto?.subtle) {
    throw new Error('Web Crypto API not available for signature verification')
  }
  const encoder = new TextEncoder()
  const keyData = encoder.encode(signingKey)
  const messageData = encoder.encode(rawBody)
  const signatureData = hexToBytes(signatureHeader)

  const key = await crypto.subtle.importKey(
    'raw',
    keyData,
    { name: 'HMAC', hash: 'SHA-256' },
    false,
    ['verify']
  )
  return crypto.subtle.verify('HMAC', key, signatureData, messageData)
}

function formatAnswers(questionsAndAnswers: CalendlyWebhookPayload['questions_and_answers']): string {
  if (!questionsAndAnswers || questionsAndAnswers.length === 0) {
    return 'No custom answers provided'
  }
  const sorted = [...questionsAndAnswers].sort((a, b) => a.position - b.position)
  return sorted.map((qa) => `${qa.question} -> ${qa.answer}`).join(', ')
}

function buildSlackText(payload: CalendlyWebhookPayload): string {
  const name = payload.name || `${payload.first_name} ${payload.last_name}`.trim()
  const email = payload.email
  const answers = formatAnswers(payload.questions_and_answers)
  return `New meeting booked!\nName: ${name}\nEmail: ${email}\nAnswers: ${answers}`
}

export async function handle(payload: ConnectorInput, config: ConnectorConfig): Promise<ConnectorResult> {
  if (!payload || typeof payload !== 'object') {
    throw new Error('Invalid payload: expected an object')
  }
  if (payload.event !== 'invitee.created') {
    throw new Error(`Unsupported event type: ${payload.event}`)
  }
  if (!payload.payload) {
    throw new Error('Missing payload in webhook event')
  }
  const invitee = payload.payload
  if (!invitee.name && !invitee.first_name) {
    throw new Error('Missing required field: invitee.name or invitee.first_name')
  }
  if (!invitee.email) {
    throw new Error('Missing required field: invitee.email')
  }
  if (!Array.isArray(invitee.questions_and_answers)) {
    throw new Error('Missing required field: invitee.questions_and_answers')
  }

  if (config.calendlySigningKey && config.webhookSignature && config.webhookRawBody) {
    const isValid = await verifySignature(config.calendlySigningKey, config.webhookRawBody, config.webhookSignature)
    if (!isValid) {
      throw new Error('Invalid webhook signature')
    }
  }

  const text = buildSlackText(invitee)
  const body = JSON.stringify({ channel: config.slackChannel, text })

  const response = await config.fetch('https://slack.com/api/chat.postMessage', {
    method: 'POST',
    headers: {
      'Authorization': `Bearer ${config.slackBotToken}`,
      'Content-Type': 'application/json',
    },
    body,
  })

  if (!response.ok) {
    const errorText = await response.text().catch(() => '')
    throw new Error(`Slack API error (${response.status} ${response.statusText}): ${errorText}`)
  }

  const data = await response.json() as { ok: boolean; channel: string; ts: string; message?: { ts: string } }
  if (!data.ok) {
    throw new Error('Slack API returned ok: false')
  }

  return {
    slackMessageTs: data.message?.ts || data.ts,
    slackChannel: data.channel,
  }
}

